@Composable private fun Cover(song:Song?,edit:Edit?,size:Int=52,uri:String?=null) {
    val c=LocalContext.current
    var embedded by remember(song?.uri,edit?.cover) { mutableStateOf<ByteArray?>(null) }
    LaunchedEffect(song?.uri,edit?.cover) { if(song!=null && edit?.cover==null) embedded=Tools.embedded(c,song) }
    val model=uri ?: edit?.cover?.takeUnless { it=="-" } ?: embedded
    Box(Modifier.size(size.dp).clip(RoundedCornerShape(if(size>100)28.dp else 14.dp)).background(Brush.linearGradient(listOf(MaterialTheme.colorScheme.surfaceVariant,MaterialTheme.colorScheme.primary.copy(alpha=0.22f)))),contentAlignment=Alignment.Center) {
        Crossfade(targetState=model,animationSpec=tween(220),label="artwork") { artwork ->
            if(artwork!=null) AsyncImage(model=artwork,contentDescription="Carátula",modifier=Modifier.fillMaxSize(),contentScale=ContentScale.Crop) else Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){Icon(Icons.Default.MusicNote,"Sin carátula",tint=MaterialTheme.colorScheme.primary,modifier=Modifier.size((size/2).dp))}
        }
    }
}
@Composable private fun Head(title:String,sub:String="") { Column(Modifier.padding(vertical=12.dp)) { Text(title,style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold); if(sub.isNotBlank()) Text(sub,color=MaterialTheme.colorScheme.onSurfaceVariant,style=MaterialTheme.typography.bodyMedium) } }
@Composable private fun SongRow(s:Song,e:Edit?,onPlay:()->Unit,onMenu:()->Unit,selected:Boolean=false) {
    Row(Modifier.fillMaxWidth().clickable(onClick=onPlay).padding(vertical=7.dp),verticalAlignment=Alignment.CenterVertically) { Cover(s,e); Column(Modifier.weight(1f).padding(horizontal=12.dp)) { Text(s.title,fontWeight=FontWeight.SemiBold,maxLines=1,overflow=TextOverflow.Ellipsis); Text("${s.artist} • ${formatTime(s.duration)}",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant,maxLines=1,overflow=TextOverflow.Ellipsis) }; if(selected || e?.favorite==true) Icon(if(selected) Icons.Default.CheckCircle else Icons.Default.Favorite,"Marcada",tint=MaterialTheme.colorScheme.primary); IconButton(onClick=onMenu) { Icon(Icons.Default.MoreVert,"Opciones") } }
}
